namespace Scheduling;

/// <summary>Finds the first calendar slot that fits a required duration.</summary>
public sealed class SlotFinder
{
    public Slot? FindFirstFit(Resource resource, TimeSpan duration, DateTime notBefore)
    {
        ArgumentNullException.ThrowIfNull(resource);

        if (duration <= TimeSpan.Zero || resource.Calendar.Count == 0)
            return null;

        return resource.Calendar.FirstOrDefault(slot =>
            slot.Start >= notBefore && IsEligible(slot, duration));
    }

    private static bool IsEligible(Slot slot, TimeSpan duration)
    {
        var dayStart = slot.Start.Date.AddHours(8);
        var latestStart = slot.Start.Date.AddHours(18);
        var dayEnd = slot.Start.Date.AddHours(20);

        return slot.End - slot.Start >= duration
            && slot.Start >= dayStart
            && slot.Start <= latestStart
            && slot.End <= dayEnd;
    }
}
